let pricingXlsxPromise=null;
function pcNormHeader(v){return pcText(v).replace(/\u200c/g,' ').replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/[\sـ_\-\/\\()\[\]،,:؛.؟?!]/g,'').toLowerCase()}
function pcLoadXlsx(){if(window.XLSX)return Promise.resolve(window.XLSX);if(pricingXlsxPromise)return pricingXlsxPromise;const sources=['./js/xlsx.full.min.js','https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js','https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js'];pricingXlsxPromise=new Promise(async(resolve,reject)=>{for(const src of sources){try{await new Promise((ok,fail)=>{const sc=document.createElement('script');sc.src=src;sc.onload=ok;sc.onerror=fail;document.head.appendChild(sc)});if(window.XLSX)return resolve(window.XLSX)}catch(e){}}reject(new Error('کتابخانه خواندن Excel بارگذاری نشد'))});return pricingXlsxPromise}
function pcFindColumn(headers,aliases){const hs=headers.map(pcNormHeader),as=aliases.map(pcNormHeader);return hs.findIndex(h=>as.some(a=>h===a||h.includes(a)))}
function pcFindColumnExactV954(headers,aliases){const hs=headers.map(pcNormHeader),as=aliases.map(pcNormHeader);return hs.findIndex(h=>as.includes(h))}
function pcNormalizeUnitV954(v){const x=pcText(v).replace(/ي/g,'ی').replace(/ك/g,'ک');return ({'کیلو':'کیلوگرم','کیلوگرم':'کیلوگرم','لیتر':'لیتر','عدد':'عدد','بسته':'بسته','گرم':'گرم'})[x]||x}
function pcJalaliV954(v){let s=pcText(v).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)),z=s.replace(/\D/g,'');if(z.length===8)return `${z.slice(0,4)}/${z.slice(4,6)}/${z.slice(6,8)}`;const m=s.match(/(\d{4})\D+(\d{1,2})\D+(\d{1,2})/);return m?`${m[1]}/${String(+m[2]).padStart(2,'0')}/${String(+m[3]).padStart(2,'0')}`:pcText(v)}
async function pcReadIngredientsExcel(event,mode){const file=event.target.files[0];event.target.value='';if(!file)return;try{const XLSX=await pcLoadXlsx(),wb=XLSX.read(await file.arrayBuffer(),{type:'array',raw:false});let best=null;for(const sheetName of wb.SheetNames){const rows=XLSX.utils.sheet_to_json(wb.Sheets[sheetName],{header:1,raw:false,defval:'',blankrows:false});for(let r=0;r<Math.min(rows.length,25);r++){const h=(rows[r]||[]).map(pcText),map={code:pcFindColumn(h,['کد ماده','کد ماده اولیه','کد کالا','کد']),name:pcFindColumn(h,['نام ماده','نام ماده اولیه','نام کالا','شرح']),category:pcFindColumn(h,['دسته بندی','دسته‌بندی','گروه','گروه ماده','نوع کالا']),purchaseUnit:pcFindColumnExactV954(h,['واحد خرید','واحد']),recipeUnit:pcFindColumn(h,['واحد مصرف','واحد رسپی','واحد مصرف در رسپی']),packageQuantity:pcFindColumn(h,['مقدار هر بسته','مقدار بسته','مقدار در بسته','ضریب تبدیل','ضریب مصرف']),price:pcFindColumn(h,['آخرین قیمت خرید تومان','آخرین قیمت خرید','قیمت خرید تومان','قیمت خرید','قیمت']),waste:pcFindColumn(h,['درصد ضایعات','درصد افت','ضایعات','افت']),date:pcFindColumn(h,['تاریخ آخرین قیمت','تاریخ خرید','تاریخ قیمت']),status:pcFindColumn(h,['وضعیت']),notes:pcFindColumn(h,['توضیحات'])};const score=(map.name>=0?3:0)+(map.code>=0?2:0)+(map.price>=0?3:0)+(map.category>=0?1:0)+(map.packageQuantity>=0?1:0);if(!best||score>best.score)best={sheetName,rows,headerRow:r,map,score,headers:h}}}
  if(!best||(best.map.name<0&&best.map.code<0)||(mode==='prices'&&best.map.price<0))throw Error('ستون‌های لازم در فایل پیدا نشد');const sepidsRaw=best.headers.some(h=>pcNormHeader(h)==='ضریبمصرف')&&best.headers.some(h=>pcNormHeader(h)==='نوعکالا')&&best.headers.some(h=>pcNormHeader(h)==='واحدمصرف');let added=0,updated=0,notFound=0,skipped=0;const norm=v=>pcNormHeader(v);for(const row of best.rows.slice(best.headerRow+1)){const get=k=>best.map[k]>=0?row[best.map[k]]:'',code=pcText(get('code')),name=pcText(get('name'));if(!code&&!name){skipped++;continue}let item=pricingState.ingredients.find(x=>(code&&norm(x.code)===norm(code))||(!code&&name&&norm(x.name)===norm(name)));if(mode==='prices'){const rawPrice=pcNum(get('price')),price=sepidsRaw?rawPrice/10:rawPrice;if(!item){notFound++;continue}if(price<=0){skipped++;continue}item.lastPurchasePriceToman=price;const d=pcJalaliV954(get('date'));if(d)item.lastPurchaseDate=d;pcRecordIngredientPrice(item.id,price,d||item.lastPurchaseDate,'excel');updated++;continue}let purchaseUnit=pcNormalizeUnitV954(get('purchaseUnit'))||item?.purchaseUnit||'',recipeUnit=pcNormalizeUnitV954(get('recipeUnit'))||item?.recipeUnit||'',packageQuantity=best.map.packageQuantity>=0?pcNum(get('packageQuantity')):(item?.packageQuantity||0);if(purchaseUnit==='کیلوگرم'&&recipeUnit==='گرم')packageQuantity=1000;const data={code:code||item?.code||pcUid('MAT',pricingState.ingredients),name:name.replace(/ي/g,'ی').replace(/ك/g,'ک')||item?.name||'',category:pcText(get('category')).replace(/ي/g,'ی').replace(/ك/g,'ک')||item?.category||'سایر',purchaseUnit,recipeUnit,packageQuantity,lastPurchasePriceToman:best.map.price>=0?(sepidsRaw?pcNum(get('price'))/10:pcNum(get('price'))):(item?.lastPurchasePriceToman||0),wastePercent:best.map.waste>=0?pcClamp(get('waste'),0,99):(item?.wastePercent||0),lastPurchaseDate:pcJalaliV954(get('date'))||item?.lastPurchaseDate||'',status:pcText(get('status'))||item?.status||'فعال',notes:pcText(get('notes'))||item?.notes||''};if(!data.name){skipped++;continue}if(item){Object.assign(item,data);updated++}else{item={id:pcUid('ING',pricingState.ingredients),...data};pricingState.ingredients.push(item);added++}if(pcNum(data.lastPurchasePriceToman)>0)pcRecordIngredientPrice(item.id,data.lastPurchasePriceToman,data.lastPurchaseDate,'excel');if(!pricingState.lists.ingredientCategories.includes(data.category))pricingState.lists.ingredientCategories.push(data.category)}await pcSaveData(false,mode==='prices'?'ورود آخرین قیمت مواد از Excel':'ورود مواد اولیه از Excel');renderView();toast(mode==='prices'?`${updated} قیمت به‌روزرسانی شد${notFound?`؛ ${notFound} مورد پیدا نشد`:''}`:`${added} ماده اضافه و ${updated} ماده به‌روزرسانی شد`)}catch(e){toast(e.message||'خواندن فایل Excel انجام نشد',true)}}
function pcExportChangesCsv(){const rows=pricingState.menuItems.filter(x=>pcMetrics(x).needs),csv=[['کد','نام','دسته','قیمت فعلی','بهای تمام‌شده','نسبت','سقف هدف','قیمت پیشنهادی','میزان افزایش'],...rows.map(i=>{const m=pcMetrics(i);return[i.code,i.name,i.category,m.price,Math.round(m.cost),m.ratio.toFixed(2),m.target,m.suggested,m.delta]})].map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n');const b=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='rayo-price-changes.csv';a.click();URL.revokeObjectURL(a.href)}
function pcExportJson(){pricingState.meta.updatedAt=new Date().toISOString();const b=new Blob([JSON.stringify(pricingState,null,2)],{type:'application/json;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='pricing-data.json';a.click();URL.revokeObjectURL(a.href)}
async function pcSaveJsonToDisk(){try{pricingState.meta.updatedAt=new Date().toISOString();if('showSaveFilePicker'in window){if(!pricingFileHandle)pricingFileHandle=await window.showSaveFilePicker({suggestedName:'pricing-data.json',types:[{description:'JSON',accept:{'application/json':['.json']}}]});const w=await pricingFileHandle.createWritable();await w.write(JSON.stringify(pricingState,null,2));await w.close();await PricingStorageAdapter.save(pricingState);toast('فایل pricing-data.json ذخیره شد')}else{pcExportJson();toast('مرورگر نوشتن مستقیم را پشتیبانی نمی‌کند؛ JSON دانلود شد')}}catch(e){if(e?.name!=='AbortError')toast('ذخیره فایل قیمت‌گذاری انجام نشد',true)}}
function pcImportJson(e){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=async()=>{try{pricingState=pcMigrate(JSON.parse(r.result));pricingLoaded=true;await PricingStorageAdapter.save(pricingState);renderView();toast('JSON قیمت‌گذاری وارد شد')}catch(err){toast('فایل JSON قیمت‌گذاری معتبر نیست',true)}};r.readAsText(f);e.target.value=''}
function installPricingModule(){if(typeof views==='undefined'||typeof titles==='undefined'||document.querySelector('[data-view="pricing"]'))return;titles.pricing='بهای تمام‌شده و قیمت‌گذاری';views.pricing=viewsPricing;const sidebar=document.querySelector('.sidebar'),groups=[...sidebar.querySelectorAll('.nav-group')],ref=groups.find(x=>x.textContent.includes('گزارش و تنظیمات'));const group=document.createElement('div');group.className='nav-group';group.textContent='منو و قیمت‌گذاری';const btn=document.createElement('button');btn.className='nav-btn';btn.dataset.view='pricing';btn.innerHTML='🧮 <span>بهای تمام‌شده و قیمت‌گذاری</span>';btn.onclick=()=>goView('pricing');sidebar.insertBefore(group,ref||null);sidebar.insertBefore(btn,ref||null);window.getPricingState=()=>pricingState;window.getPricingLoadSource=()=>PRICING_APP_CONFIG.lastLoadSource||'';window.ensurePricingLoaded=pcEnsureLoaded;window.pricingUI=pricingUI;window.pcEnsureLoaded=pcEnsureLoaded;window.pcRefreshData=pcRefreshData;window.pcSaveData=pcSaveData;window.pcSaveJsonToDisk=pcSaveJsonToDisk;window.pcExportJson=pcExportJson;window.pcImportJson=pcImportJson;window.pcEditMenuItem=pcEditMenuItem;window.pcMenuCategoryChanged=pcMenuCategoryChanged;window.pcSaveMenuItem=pcSaveMenuItem;window.pcEditIngredient=pcEditIngredient;window.pcSaveIngredient=pcSaveIngredient;window.pcToggleOperationalFields=pcToggleOperationalFields;window.pcOpenRecipe=pcOpenRecipe;window.pcEditRecipeLine=pcEditRecipeLine;window.pcRecipeUnitRefresh=pcRecipeUnitRefresh;window.pcSaveRecipeLine=pcSaveRecipeLine;window.pcDeleteRecipeLine=pcDeleteRecipeLine;window.pcApplySuggestedPrice=pcApplySuggestedPrice;window.pcRoundApplyPrice=pcRoundApplyPrice;window.pcConfirmAppliedPrice=pcConfirmAppliedPrice;window.pcDeleteMenuItem=pcDeleteMenuItem;window.pcDeleteIngredient=pcDeleteIngredient;window.pcSaveSettings=pcSaveSettings;window.pcExportChangesCsv=pcExportChangesCsv;window.pcReadIngredientsExcel=pcReadIngredientsExcel;window.pcAddCategoryRow=pcAddCategoryRow;window.pcRemoveCategoryRow=pcRemoveCategoryRow;window.pcAddIngredientCategoryRow=pcAddIngredientCategoryRow;window.pcRemoveIngredientCategoryRow=pcRemoveIngredientCategoryRow}
